ALTER TABLE public.profiles ADD COLUMN legacy_organization_id uuid REFERENCES public.organizations(id);
UPDATE public.profiles SET legacy_organization_id=(SELECT id FROM public.organizations WHERE slug='foxes-darts');
INSERT INTO public.organization_players(organization_id,user_id) SELECT legacy_organization_id,id FROM public.profiles WHERE legacy_organization_id IS NOT NULL ON CONFLICT DO NOTHING;
COMMENT ON COLUMN public.profiles.legacy_organization_id IS 'Immutable historical provenance only; not a user role or automatic membership for future accounts.';
REVOKE UPDATE ON public.profiles FROM authenticated;
GRANT UPDATE(display_name,tournament_announcements,tournaments_seen_at,first_name,last_name,avatar_path) ON public.profiles TO authenticated;
CREATE FUNCTION public.profile_readable_by_manager(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_platform_admin() OR EXISTS(SELECT 1 FROM public.organization_players p WHERE p.user_id=_user_id AND public.can_manage_organization(p.organization_id)) OR EXISTS(SELECT 1 FROM public.organization_members m WHERE m.user_id=_user_id AND public.can_manage_organization(m.organization_id)) $$;
REVOKE ALL ON FUNCTION public.profile_readable_by_manager(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.profile_readable_by_manager(uuid) TO authenticated,service_role;
ALTER POLICY "Users read own profile, admins read all" ON public.profiles USING(auth.uid()=id OR public.profile_readable_by_manager(id));
ALTER POLICY "Admins can manage player stats" ON public.player_stats WITH CHECK(public.is_platform_admin());
ALTER POLICY "Admins can update player stats" ON public.player_stats USING(public.is_platform_admin()) WITH CHECK(public.is_platform_admin());
ALTER POLICY "Admins can delete player stats" ON public.player_stats USING(public.is_platform_admin());
ALTER POLICY "Admins read games" ON public.games USING(recorded_by=auth.uid() OR public.is_platform_admin() OR (tournament_id IS NOT NULL AND public.can_manage_tournament(tournament_id)));
CREATE FUNCTION public.media_organization_id(_path text) RETURNS uuid LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN IF _path LIKE '%..%' OR position(E'\\' in _path)>0 THEN RETURN NULL; END IF; IF _path ~ '^organizations/[0-9a-fA-F-]{36}/(tournaments|photos|highlights)/[^/]+$' THEN BEGIN result:=split_part(_path,'/',2)::uuid; EXCEPTION WHEN invalid_text_representation THEN RETURN NULL; END; RETURN result; END IF; IF _path ~ '^(tournaments|photos|highlights)/[^/]+$' THEN SELECT id INTO result FROM public.organizations WHERE slug='foxes-darts'; RETURN result; END IF; RETURN NULL; END $$;
REVOKE ALL ON FUNCTION public.media_organization_id(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.media_organization_id(text) TO anon,authenticated,service_role;
ALTER POLICY "Admins can upload tournament photos" ON storage.objects WITH CHECK(bucket_id='tournament-photos' AND name LIKE 'organizations/%' AND public.can_manage_organization(public.media_organization_id(name)));
ALTER POLICY "Admins can read tournament photos" ON storage.objects USING(bucket_id='tournament-photos' AND public.can_manage_organization(public.media_organization_id(name)));
ALTER POLICY "Admins can update tournament photos" ON storage.objects USING(bucket_id='tournament-photos' AND public.can_manage_organization(public.media_organization_id(name))) WITH CHECK(bucket_id='tournament-photos' AND public.can_manage_organization(public.media_organization_id(name)));
ALTER POLICY "Admins can delete tournament photos" ON storage.objects USING(bucket_id='tournament-photos' AND public.can_manage_organization(public.media_organization_id(name)));
CREATE FUNCTION public.enforce_media_organization() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE path text; BEGIN IF TG_TABLE_NAME='tournaments' THEN path:=NEW.image_url; ELSIF TG_TABLE_NAME='photos' THEN path:=NEW.image_url; ELSE path:=NEW.media_url; END IF; IF path IS NOT NULL AND path !~ '^https?://' AND public.media_organization_id(path) IS DISTINCT FROM NEW.organization_id THEN RAISE EXCEPTION 'Image does not belong to this organization'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.enforce_media_organization() FROM PUBLIC;
CREATE TRIGGER tournaments_media_integrity BEFORE INSERT OR UPDATE ON public.tournaments FOR EACH ROW EXECUTE FUNCTION public.enforce_media_organization();
CREATE TRIGGER photos_media_integrity BEFORE INSERT OR UPDATE ON public.photos FOR EACH ROW EXECUTE FUNCTION public.enforce_media_organization();
CREATE TRIGGER highlights_media_integrity BEFORE INSERT OR UPDATE ON public.highlights FOR EACH ROW EXECUTE FUNCTION public.enforce_media_organization();
CREATE FUNCTION public.set_central_member_admin(_user_id uuid,_admin boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE central_id uuid; old_role text; BEGIN SELECT id INTO central_id FROM public.organizations WHERE slug='foxes-darts' AND status='active'; IF central_id IS NULL OR NOT public.can_manage_organization(central_id) THEN RAISE EXCEPTION 'Forbidden'; END IF; PERFORM 1 FROM public.organizations WHERE id=central_id FOR UPDATE; IF _user_id=auth.uid() AND NOT _admin THEN RAISE EXCEPTION 'Cannot remove own admin access'; END IF; IF NOT EXISTS(SELECT 1 FROM public.organization_players WHERE organization_id=central_id AND user_id=_user_id) THEN RAISE EXCEPTION 'Player does not belong to this organization'; END IF; SELECT role INTO old_role FROM public.organization_members WHERE organization_id=central_id AND user_id=_user_id; IF old_role='ORGANIZATION_OWNER' THEN RAISE EXCEPTION 'Owner is protected'; END IF; IF _admin THEN INSERT INTO public.organization_members(organization_id,user_id,role) VALUES(central_id,_user_id,'ORGANIZATION_ADMIN') ON CONFLICT(organization_id,user_id) DO UPDATE SET role='ORGANIZATION_ADMIN'; ELSE DELETE FROM public.organization_members WHERE organization_id=central_id AND user_id=_user_id AND role='ORGANIZATION_ADMIN'; END IF; INSERT INTO public.organization_audit_events(organization_id,actor_id,action,details) VALUES(central_id,auth.uid(),'organization.member.role_changed',jsonb_build_object('user_id',_user_id,'previous_role',old_role,'admin',_admin)); END $$;
REVOKE ALL ON FUNCTION public.set_central_member_admin(uuid,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_central_member_admin(uuid,boolean) TO authenticated;
COMMENT ON TABLE public.user_roles IS 'DEPRECATED: legacy role rows retained for history, no longer used for organization permissions, media, profile access or global statistics.';